contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(address(this).balance >= depositAmount);
        require(depositAmount > 1 ether);
        require(cashOutAmount <= depositAmount);

        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        assert(
            (!reverted && balBefore == balAfter + cashOutAmount && cBalBefore == cBalAfter + cashOutAmount) ||
            (reverted && balAfter == balBefore && cBalAfter == cBalBefore)
        );
    }

    receive() external payable {}
}

