    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint depositAmount, uint cashOutAmount) public payable {
        // Deposit exactly `depositAmount` by sending it as msg.value.
        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint cEtherBefore = address(c).balance;
        uint expectedBalAfter = balBefore - cashOutAmount;

        bool reverted;
        try c.CashOut(cashOutAmount) {
            reverted = false;
