import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 depositAmount, uint256 withdrawAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 1 ether);
        vm.assume(withdrawAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint beforeC = address(c).balance;
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        vm.assume(withdrawAmount <= beforeBal);
        bool reverted;
        try c.CashOut(withdrawAmount) { reverted = false; } catch { reverted = true; }
        uint afterC = address(c).balance;
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(!reverted && afterC == beforeC - withdrawAmount && afterBal == beforeBal - withdrawAmount);
    }

    function testFuzz_run(uint256 depositAmount, uint256 withdrawAmount) public {
        _run(depositAmount, withdrawAmount);
    }

    receive() external payable {}
}

